$MOD = 998244353;

function pw($a, $b) {
    $MOD = 998244353;
    $res = 1;
    $a %= $MOD;
    while ($b > 0) {
        if ($b & 1) $res = $res * $a % $MOD;
        $a = $a * $a % $MOD;
        $b >>= 1;
    }
    return $res;
}

$line = trim(fgets(STDIN));
$parts = preg_split('/\s+/', $line);
$p = (int)$parts[0];
$s = (int)$parts[1];
$r = (int)$parts[2];

$N = $s + $p + 10;
$f = array_fill(0, $N + 1, 1);
for ($i = 1; $i <= $N; $i++) $f[$i] = $f[$i-1] * $i % $MOD;
$fi = array_fill(0, $N + 1, 1);
$fi[$N] = pw($f[$N], $MOD - 2);
for ($i = $N; $i >= 1; $i--) $fi[$i-1] = $fi[$i] * $i % $MOD;

function C($n, $k) {
    global $f, $fi, $MOD, $N;
    if ($k < 0 || $n < 0 || $k > $n) return 0;
    if ($n > $N) return 0;
    return $f[$n] * $fi[$k] % $MOD * $fi[$n-$k] % $MOD;
}

// inverses of 1..p
$inv = array_fill(0, $p + 2, 1);
for ($i = 1; $i <= $p + 1; $i++) $inv[$i] = pw($i, $MOD - 2);

$total = C($s - $r + $p - 1, $p - 1);

$ans = 0;
for ($m = $r; $m <= $s; $m++) {
    if ($m == 0) {
        if ($s == 0) {
            $ans = ($ans + $inv[$p]) % $MOD;
        }
        continue;
    }
    for ($k = 0; $k <= $p - 1; $k++) {
        $T = $s - $m * ($k + 1);
        if ($T < 0) break;
        $j = $p - 1 - $k;
        $ways = 0;
        if ($j == 0) {
            $ways = ($T == 0) ? 1 : 0;
        } else {
            for ($i = 0; $i <= $j; $i++) {
                $rem = $T - $i * $m;
                if ($rem < 0) break;
                $term = C($j, $i) * C($rem + $j - 1, $j - 1) % $MOD;
                if ($i & 1) {
                    $ways = ($ways - $term + $MOD) % $MOD;
                } else {
                    $ways = ($ways + $term) % $MOD;
                }
            }
        }
        if ($ways == 0) continue;
        $add = C($p - 1, $k) * $inv[$k + 1] % $MOD * $ways % $MOD;
        $ans = ($ans + $add) % $MOD;
    }
}

$ans = $ans * pw($total, $MOD - 2) % $MOD;
echo $ans . "\n";
